mapper.select:
select , qad.sku_id as skuId, qad.sku_no as skuNo, qad.supplier_id as supplierId, pd.name as productName, qnd.qc_status as qcStatus, qr.qc_result as qcResult, qr.lot_qualified_qty as batchQty, qnd.qc_good_qty as qcGoodQty, qnd.qc_bad_qty as qcBadQty, qnd.qc_qty as qcQty, qad.qty from qc_application qa inner join qc_application_detail qad on qa.id = qad.main_id and qad.is_deleted = FALSE left join product_detail pd on pd.id = qad.sku_id and pd.is_deleted = FALSE left join qc_notice qn on qa.id = qn.source_id and qn.is_deleted = false left join qc_notice_detail qnd on qad.id = qnd.source_detail_id and qnd.is_deleted = false left join qc_info qi on qn.id = qi.source_id and qnd.id = qi.source_detail_id and qi.is_deleted = false left join qc_result qr on qi.id = qr.main_id and qr.is_deleted = false WHERE ${params.sqlMap.default} and qa.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
qa.id DESC

SELECT approve_status AS tabFlag, count(*) AS count FROM qc_application WHERE is_deleted=FALSE
${params.permissionSql}
GROUP BY approve_status
